/**
 * Wave 1 games — make ARK, Satisfactory, Project Zomboid, 7 Days to Die, V Rising
 * and Enshrouded orderable. Each is a Docker container (community image) installed
 * by the OsTemplate.setupScript in cloud-init — same pattern as Minecraft/Rust/Valheim.
 *
 * Creates:
 *   1. An OsTemplate per game (family=<game>, category=APPLICATION, setupScript = the
 *      one-line docker run). Clones the golden Ubuntu template (baseVmid 9000).
 *   2. GamePlan tiers, each wired to the smallest active VPS Plan whose ramMB >= the
 *      tier's ramMB + this game's OsTemplate.
 *
 * Idempotent: OsTemplates upsert by slug; GamePlans dedupe by (gameFamily, name).
 * Run: cd /opt/nxeon && npx tsx prisma/seed-wave1-games.ts
 *
 * NOTE: default in-container passwords are the static placeholder "changeme12"
 * (matching the existing Valheim template) — customers change them post-deploy.
 * A per-order random-secret injection is a follow-up security refinement.
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type Template = {
  family: string;
  name: string;
  setupScript: string;
  minRamMB: number;
  minDiskGB: number;
};

const TEMPLATES: Template[] = [
