async function main() {
  for (const it of CATALOG) {
    const vmid = BASE[it.base];
    const data = {
      name: it.name,
      category: it.category,
      family: it.family,
      version: it.version ?? "",
      logo: it.logo,
      vmid,

    minRamMB: 8192,
