1	/**
2	 * Steam Web API client for automating Game Server Login Tokens (GSLTs) —
3	 * the credential a Source-engine dedicated server (CS2 today; app 730) needs
4	 * to register with Steam matchmaking at all. Without one, `worker/game-config.ts`
5	 * has nothing to write into SRCDS_TOKEN and the server never appears — the
6	 * exact gap a real customer hit live 2026-09-16 (cs2-dbhy4p), fixed at the
7	 * checkout-wizard level by asking for it, and fixed here by not needing to ask
8	 * at all: a hosting account can mint these on a customer's behalf via
9	 * IGameServersService, the same interface every serious CS2 host automates
10	 * against (confirmed live against Valve's own partner docs, not assumed).
11	 *
12	 * Auth is a single Steamworks Web API key (Basic-auth-free, passed as a
13	 * `key` query/body param) — obtained by a Steam account owner filling out
14	 * the form at steamcommunity.com/dev and agreeing to the Steam API Terms of
15	 * Use. One key/account can hold up to 1000 persistent game-server accounts
16	 * (Valve's documented ceiling); DeleteAccount below exists specifically so a
17	 * cancelled server's token is freed back into that budget instead of leaking.
18	 */
19	
20	const BASE = "https://api.steampowered.com/IGameServersService";
21	
22	export function steamGsltConfigured(): boolean {
23	  return !!process.env.STEAM_WEB_API_KEY;
24	}
25	
26	async function call(method: string, params: Record<string, string | number>): Promise<any> {
27	  if (!steamGsltConfigured()) throw new Error("Steam Web API key is not configured");
28	  const key = process.env.STEAM_WEB_API_KEY!;
29	  // IGameServersService is a "Service" interface (name ends in "Service") —
30	  // confirmed live 2026-09-17 the hard way: individual form fields silently
31	  // no-op (a 200 with an empty {"response":{}}, no error at all) rather than
32	  // being rejected. Per Valve's own Web API overview, every Service-interface
33	  // method takes its real arguments as ONE url-encoded JSON blob in
34	  // `input_json`; `key` stays a separate top-level param.
35	  const body = new URLSearchParams({ key, input_json: JSON.stringify(params) });
36	  const res = await fetch(`${BASE}/${method}/v1/`, {
37	    method: "POST",
38	    headers: { "Content-Type": "application/x-www-form-urlencoded" },
39	    body: body.toString(),
40	    signal: AbortSignal.timeout(20_000),
41	  });
42	  const text = await res.text();
43	  let json: any = null;
44	  try {
45	    json = text ? JSON.parse(text) : null;
46	  } catch {
47	    json = text;
48	  }
49	  // Confirmed live 2026-09-17: a rejected call from a Service interface can
50	  // come back as a plain 200 with an EMPTY {"response":{}} body — the real
51	  // reason lives in the `x-eresult`/`x-error_message` response HEADERS, not
52	  // the body or the HTTP status. (Account does not have a registered phone
53	  // number" was the actual failure the first time this ran, surfaced only
54	  // this way.) Check both: a non-2xx status, or a non-1 (k_EResultOK)
55	  // x-eresult on an otherwise-200 response.
56	  const eresult = res.headers.get("x-eresult");
57	  const errorMessage = res.headers.get("x-error_message");
58	  if (!res.ok || (eresult && eresult !== "1")) {
59	    // Never leak the API key into a thrown message or log line.
60	    throw new Error(
61	      `Steam ${method} -> ${res.status}${eresult ? ` (eresult ${eresult})` : ""}: ` +
62	        `${errorMessage ?? (typeof json === "string" ? json : JSON.stringify(json))}`,
63	    );
64	  }
65	  return json;
66	}
67	
68	export type SteamGameServerAccount = { steamid: string; loginToken: string };
69	
70	/**
71	 * Mint a new persistent game-server account + GSLT for `appid` (730 = CS2).
72	 * `memo` is Valve's own free-text label for the account (shown to the owning
73	 * Steam account at steamcommunity.com/dev/managegameservers) — pass something
74	 * that lets a human trace it back to the Nxeon server that owns it.
75	 *
76	 * Response field names are NOT fully documented by Valve (confirmed while
77	 * building this — partner.steamgames.com describes CreateAccount's inputs
78	 * but not its output shape). Parsed defensively across every plausible key
79	 * name seen in the wild rather than assumed, and throws with the RAW
80	 * response on a genuine mismatch so the first real call in production
81	 * fails loudly and diagnosably instead of silently storing `undefined`.
82	 */
83	export async function createGameServerAccount(appid: number, memo: string): Promise<SteamGameServerAccount> {
84	  const json = await call("CreateAccount", { appid, memo });
85	  const r = json?.response ?? json ?? {};
86	  const steamid = r.steamid ?? r.steamId ?? r.SteamID ?? r.server_steamid;
87	  const loginToken = r.login_token ?? r.loginToken ?? r.LoginToken ?? r.token;
88	  if (!steamid || !loginToken) {
89	    throw new Error(
90	      `Steam CreateAccount returned an unrecognised shape — got ${JSON.stringify(json)}. ` +
91	        `Check the real field names against this response and update createGameServerAccount's parsing.`,
92	    );
93	  }
94	  return { steamid: String(steamid), loginToken: String(loginToken) };
95	}
96	
97	/** Frees a game-server account back into the account's 1000-account budget.
98	 *  Best-effort by every caller — a cancelled server should never fail to
99	 *  delete just because Valve's side of this one cleanup step errored. */
100	export async function deleteGameServerAccount(steamid: string): Promise<void> {
101	  await call("DeleteAccount", { steamid });
102	}
