// ---------------------------------------------------------------------------
// Wave 11 (2026-09-24) — DayZ.
//
// The Wave 4 blocker (non-anonymous Steam login — see lib/games.ts and
// lib/dayz-steam.ts) is solved at the provisioning layer, not here; this
// schema only needed to solve DayZ's SECOND real gap: serverDZ.cfg is a
// file-based config (Bohemia's own `key = value;` cfg syntax, verified
// against a real reference file — see the DAYZ_CFG_* constants and applyDayZ
// in worker/game-config.ts), not a docker-env-driven image the way most of
// this catalog is. Every field below is therefore intentionally envKey-free
// — applyGameConfigEnv (worker/game-variant.ts) correctly no-ops for all of
// them (no `-e KEY=` placeholder exists in this family's setupScript to
// substitute into) — and reaches the live server exclusively through
// worker/game-config.ts's REAL_APPLY_FAMILIES SFTP read-modify-write path
// (applyDayZ), the same mechanism already verified live for Minecraft's
// server.properties. "dayz" is in REAL_APPLY_FAMILIES (see that file) so
// this reaches the server both at first provision (worker/index.ts's
// auto-queued GAME_CONFIG job for any non-default checkout value) and on
// every later Settings save — see applyDayZ's own comment for exactly what
// was and wasn't verified live (no real Steam account exists in this
// environment to actually boot a DayZ container against).
// ---------------------------------------------------------------------------

const DAYZ: FamilySchema = {
  family: "dayz", label: "DayZ", defaultVariant: "vanilla",
  variants: [{ id: "vanilla", label: "Vanilla", description: "Standard DayZ dedicated server, no server-side mods." }],
  fields: [
    { key: "hostname", label: "Server Name", group: "General", type: "string", default: "Nxeon DayZ Server", phase: "deploy", help: "serverDZ.cfg key: hostname." },
    { key: "password", label: "Server Password", group: "Access", type: "string", default: "", phase: "deploy", help: "serverDZ.cfg key: password. Blank = open server." },
    // Real in-game admin login (players type `#login <this>` in chat) — unlike
    // Palworld's ADMIN_PASSWORD this is NOT an RCON/platform-control secret
    // (DayZ's RCON is BattlEye's, wired separately — see lib/game-control.ts),
    // so it's a genuinely customer-facing field, not one worker/index.ts
    // overwrites with a generated secret at provision time.
    { key: "passwordAdmin", label: "Admin Password", group: "Access", type: "string", default: "", phase: "deploy", help: "serverDZ.cfg key: passwordAdmin — in-game #login access. Blank disables in-game admin login entirely." },
    { key: "maxPlayers", label: "Max Players", group: "General", type: "int", default: 60, min: 1, max: 60, phase: "deploy", help: "serverDZ.cfg key: maxPlayers. 60 is the officially supported ceiling." },
    // The Missions/DayZ/template key is NESTED two classes deep in the real
    // file (`class Missions { class DayZ { template = "..."; }; };`), not a
    // flat top-level key like the four above — applyDayZ's cfg writer handles
    // that nesting explicitly, it is not a generic flat key=value patch.
    // Livonia/Sakhal are real, multi-source-confirmed mission template
    // strings (community DayZ server-file repos, cross-checked against 2+
    // independent sources each since Bohemia's own wiki 403s server-side
    // fetches) but UNVERIFIED whether Nxeon's dedicated Steam account (see
    // lib/dayz-steam.ts) would also need to separately own the Frostline
    // (Sakhal) / Livonia DLC to serve those maps — flagged, not guessed past.
    {
      key: "missionTemplate", label: "Mission / Map", group: "General", type: "enum", default: "dayzOffline.chernarusplus", phase: "deploy",
      options: [
        { value: "dayzOffline.chernarusplus", label: "Chernarus (base map)" },
        { value: "dayzOffline.enoch", label: "Livonia" },
        { value: "dayzOffline.sakhal", label: "Sakhal (Frostline)" },
      ],
      help: "Livonia/Sakhal are paid DLC maps — confirm Nxeon's hosting Steam account owns the DLC before offering these for real; Chernarus needs nothing extra.",
    },
  ],
};

/** Family → schema. Only families with a customization schema appear here. */
export const GAME_CONFIG_SCHEMAS: Record<string, FamilySchema> = {

