135	export async function gameConfigApply(job: Job): Promise<void> {
136	  const serverId = job.serverId;
137	  if (!serverId) throw new Error("game config: job has no serverId");
138	
139	  const server = await db.server.findUnique({
140	    where: { id: serverId },
141	    include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true },
142	  });
143	  if (!server) throw new Error(`Server ${serverId} not found`);
144	
145	  const family = familyFor(server);
146	  const schema = schemaFor(family);
147	  if (!family || !schema) {
148	    throw new Error(`game config: ${server.hostname} is not a customizable game server`);
149	  }
150	
151	  const variant = server.gameVariant ?? schema.defaultVariant;
152	  const realApply = familyRealApplyEnabled(family);
153	
154	  // -------------------------------------------------------------------------
155	  // Simulation is a SANDBOX affordance and MUST NEVER run in production.
156	  //
157	  // Until 2026-07-26 it did: production has no ENABLE_REAL_GAMECFG, so every real
158	  // customer request fell through to the block below, stamped an `_appliedAt`
159	  // marker, and notified them "Game settings applied on <hostname>" — with the
160	  // "(sandbox)" suffix suppressed, because SANDBOX is false on production. So the
161	  // customer changed their difficulty or slot count, was told it was applied, and
162	  // nothing on the server had changed.
163	  //
164	  // Identical in kind to the SSL bug fixed the same day, where production wrote a
165	  // certificate row as ACTIVE with an invented expiry while no certbot had run:
166	  // the system asserting an outcome it never performed. A change we did not apply
167	  // is a FAILURE, and it must say so loudly enough that an operator notices the
168	  // flag is missing.
169	  // -------------------------------------------------------------------------
170	  if (!realApply && !SANDBOX) {
171	    throw new Error(
172	      "Game settings could not be applied: real application is switched off on this " +
173	        "server (ENABLE_REAL_GAMECFG is not set), so nothing was written to the game " +
174	        "server and your settings are NOT in effect. Please contact support."
175	    );
176	  }
177	
178	  if (!realApply) {
179	    const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
180	    const marker = {
181	      _appliedVariant: variant,
182	      _appliedAt: new Date().toISOString(),
183	      _configVersion: GAME_CONFIG_VERSION,
184	      _sandbox: SANDBOX,
185	    };
186	
187	    await db.server.update({
188	      where: { id: server.id },
189	      data: { gameConfig: { ...existing, ...marker } as any },
190	    });
191	
192	    await notify(
193	      server.userId,
194	      `Game settings applied on ${server.hostname}`,
195	      `${schema.label} (${variant}) settings were applied${SANDBOX ? " (sandbox)" : ""}.`,
196	      `/dashboard/servers/${server.id}?tab=game settings`
197	    );
198	    return;
199	  }
200	
201	  // -------------------------------------------------------------------------
202	  // REAL PATH — gated behind ENABLE_REAL_GAMECFG. Everything below is wrapped so
203	  // a failure notifies the user but never throws out of the handler.
204	  // -------------------------------------------------------------------------
205	  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
206	  const valid = validateConfig(family, existing);
207	  // `existing` also holds the `_`-prefixed markers; validateConfig drops unknown
208	  // keys, so `values` is exactly the schema fields keyed on the game's own keys.
209	  const values = valid.ok ? valid.values : {};
210	
211	  let outcome: ApplyOutcome = { ok: false, applied: [], notes: [] };
212	  try {
213	    outcome = await applyRealConfig(server, family, values);
214	  } catch (e) {
215	    const msg = e instanceof Error ? e.message : String(e);
216	    console.error(`[game-config] real apply failed on ${server.hostname}:`, e);
217	    outcome = { ok: false, applied: [], notes: [`Apply failed: ${msg}`] };
218	  }
219	
220	  // Always record the applied-marker (even on partial/soft failure) so the portal
221	  // reflects the attempt, and note whether the real push succeeded.
222	  const marker = {
223	    _appliedVariant: variant,
224	    _appliedAt: new Date().toISOString(),
225	    _configVersion: GAME_CONFIG_VERSION,
226	    _sandbox: SANDBOX,
227	    _real: true,
228	    _realOk: outcome.ok,
229	  };
230	  try {
231	    await db.server.update({
232	      where: { id: server.id },
233	      data: { gameConfig: { ...existing, ...marker } as any },
234	    });
235	  } catch (e) {
236	    console.error("[game-config] marker update failed", e);
237	  }
238	
239	  const detail = [...outcome.applied, ...outcome.notes].join(" ");
240	  await notify(
241	    server.userId,
242	    outcome.ok
243	      ? `Game settings applied on ${server.hostname}`
244	      : `Game settings partially applied on ${server.hostname}`,
245	    `${schema.label} (${variant}) — ${detail || "no changes were made."}`,
246	    `/dashboard/servers/${server.id}?tab=game settings`
247	  );
248	}
249	
250	// ===========================================================================
251	// Real apply — per-family rendering + SSH transport
252	// ===========================================================================
253	
254	type Values = Record<string, string | number | boolean>;
255	type ApplyOutcome = { ok: boolean; applied: string[]; notes: string[] };
256	
257	/** The minimal Server shape the real path needs to open an SSH connection. */
258	export type SshServer = {
259	  id: string;
260	  rootPassword: string | null;
261	  rootPasswordEnc?: string | null;
262	  sshPort: number | null;
263	  dedicatedIp?: { address: string } | null;
264	  node?: { publicIp: string } | null;
265	  gameVariant?: string | null;
266	};
267	
268	/**
269	 * Connect to the game-server VM (host/port derived exactly like the file manager,
270	 * user "root", password `rootPassword`), run `fn`, and always close the session.
271	 */
272	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
273	  return new Promise((resolve, reject) => {
274	    const target = connectionTarget(server as any);
275	    if (!target) {
276	      reject(new Error("server is not reachable yet — connection details are pending"));
277	      return;
278	    }
279	    const password = serverRootPassword(server);
280	    if (!password) {
281	      reject(new Error("server has no root password set"));
282	      return;
283	    }
284	
285	    const conn = new Client();
286	    let settled = false;
287	    const finish = (err: Error | null, val?: T) => {
288	      if (settled) return;
289	      settled = true;
290	      try {
291	        conn.end();
292	      } catch {
293	        /* best-effort */
294	      }
295	      if (err) reject(err);
296	      else resolve(val as T);
297	    };
298	
299	    conn.on("ready", () => {
300	      conn.sftp((err, sftp) => {
301	        if (err) return finish(err);
302	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
303	      });
304	    });
305	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
306	    conn.connect({
307	      host: target.host,
308	      port: target.port,
309	      username: "root",
310	      password,
311	      readyTimeout: CONNECT_TIMEOUT_MS,
312	    });
313	  });
314	}
315	
316	/** Read a remote text file, or null if it does not exist. */
317	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
318	  return new Promise((resolve, reject) => {
319	    sftp.readFile(path, (err, data) => {
320	      if (err) {
321	        // ENOENT / no such file → null; anything else is a real error.
322	        const code = (err as NodeJS.ErrnoException).code;
323	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
324	          return resolve(null);
325	        }
326	        return reject(err);
327	      }
328	      resolve(data.toString("utf8"));
329	    });
330	  });
331	}
332	
333	/** Write a remote text file (overwrites). */
334	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
335	  return new Promise((resolve, reject) => {
336	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
337	  });
338	}
339	
340	/** Write a remote binary file (overwrites) — same as sftpWrite but skips utf8 re-encoding. */
341	function sftpWriteBinary(sftp: SFTPWrapper, path: string, content: Buffer): Promise<void> {
342	  return new Promise((resolve, reject) => {
343	    sftp.writeFile(path, content, (err) => (err ? reject(err) : resolve()));
344	  });
345	}
346	
347	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
348	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
349	  return new Promise((resolve, reject) => {
350	    conn.exec(cmd, (err, stream: ClientChannel) => {
351	      if (err) return reject(err);
352	      let stdout = "";
353	      let stderr = "";
354	      const timer = setTimeout(() => {
355	        try {
356	          stream.close();
357	        } catch {
358	          /* ignore */
359	        }
360	      }, EXEC_TIMEOUT_MS);
361	      stream
362	        .on("close", (code: number) => {
363	          clearTimeout(timer);
364	          resolve({ code: code ?? 0, stdout, stderr });
365	        })
366	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
367	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
368	    });
369	  });
370	}
371	
372	/**
373	 * Locate the first existing path: try explicit candidates via `test -f`, then a
374	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
375	 * Non-destructive — only reads.
376	 */
377	async function remoteLocate(
378	  conn: Client,
379	  candidates: string[],
380	  findRoots: string[],
381	  findName: string
382	): Promise<string | null> {
383	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
384	  const findExpr = findRoots.length
385	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
386	    : "true";
387	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
388	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
389	  return hit ?? null;
390	}
391	
392	/** Escape a value for single-quoted shell use. */
393	function shq(s: string): string {
394	  return s.replace(/'/g, "'\\''");
