 * to REAL_APPLY_FAMILIES in lib/game-config.ts.
 */
async function applyDayZ(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
  const path = await remoteLocate(
    conn,
    [
      "/opt/dayz/serverfiles/dayz/saves/serverDZ.cfg",
      "/opt/dayz/serverfiles/saves/serverDZ.cfg",
      "/opt/dayz/serverfiles/serverDZ.cfg",
    ],
    ["/opt/dayz"],
    "serverDZ.cfg"
  );
  if (!path) {
    return {
      ok: false,
      applied: [],
      notes: ["Could not locate serverDZ.cfg — nothing was changed (a restart is needed once the config path is confirmed against a live server)."],
    };
  }

  const existing = await sftpRead(sftp, path);
  if (existing == null) {
    return { ok: false, applied: [], notes: [`serverDZ.cfg disappeared at ${path} — nothing was changed.`] };
  }

  const flatUpdates: Record<string, string> = {};
  for (const key of ["hostname", "password", "passwordAdmin", "maxPlayers"]) {
    if (v[key] === undefined || v[key] === null) continue;
    flatUpdates[key] = String(v[key]);
  }
  const missionTemplate = v["missionTemplate"] != null ? String(v["missionTemplate"]) : undefined;

  const next = updateDayZConfig(existing, flatUpdates, missionTemplate);
  await sftpWrite(sftp, path, next);

  const changedCount = Object.keys(flatUpdates).length + (missionTemplate !== undefined ? 1 : 0);
  const applied: string[] = [`Wrote ${changedCount} setting(s) to ${path}.`];

  // serverDZ.cfg has no hot-reload/RCON push path (unlike Minecraft) — every
  // field here needs a restart, always. Through whichever supervisor owns
  // the container (see resolveGameUnit's own comment for why a bare `docker
  // restart` is wrong on a systemd-wrapped server).
  const unit = await resolveGameUnit(conn, "dayz");
  const restart = await execRemote(conn, unit ? `systemctl restart '${shq(unit)}'` : `docker restart ${DAYZ_CONTAINER}`);
  const notes: string[] =
    restart.code === 0
      ? ["Restarted the server to apply the new settings — any connected players were disconnected and can rejoin now."]
      : ["Wrote the new settings, but the restart could not be confirmed — restart the server manually from the Power tab."];

  return { ok: true, applied, notes };
}

