import { test } from "node:test";
import assert from "node:assert/strict";
import { updateDayZConfig } from "../worker/game-config.ts";

/**
 * DayZ's serverDZ.cfg templating — the "config-file gap" this family was
 * blocked on (see lib/game-config.ts's DAYZ schema comment and
 * lib/dayz-steam.ts for the OTHER gap, the Steam login).
 *
 * There is no live DayZ server anywhere in this environment to test against
 * (no Steam account exists to actually download one — see
 * worker/game-config.ts's applyDayZ comment for exactly what that means for
 * verification status). What CAN be verified without one, and is verified
 * here: that `updateDayZConfig` — the pure function that does the actual
 * patching `applyDayZ` calls over SFTP — correctly rewrites a REAL DayZ
 * config file with distinctive test values, without corrupting anything it
 * didn't touch.
 *
 * REFERENCE is fetched verbatim (2026-09-24) from
 * github.com/thelastnoc/dayz-sa_linuxserver's own serverDZ.cfg — a real,
 * community-maintained example of the actual file DayZ's dedicated server
 * reads, not a hand-written guess at the syntax. Kept whole (comments,
 * spacing, the full key set) specifically so these tests catch the trap the
 * real file contains: both `maxPlayers` AND `loginQueueMaxPlayers` exist in
 * it, which is exactly the kind of substring collision a naive patch breaks.
 */
const REFERENCE = `hostname = "EXAMPLE NAME";  // Server name
password = "";              // Password to connect to the server
passwordAdmin = "";         // Password to become a server admin

maxPlayers = 60;            // Maximum amount of players

verifySignatures = 2;       // Verifies .pbos against .bisign files. (only 2 is supported)

forceSameBuild = 1;         // When enabled, the server will allow the connection only to clients with same the .exe revision as the server (value 0-1)

disableVoN = 0;             // Enable/disable voice over network (value 0-1)
vonCodecQuality = 20;        // Voice over network codec quality, the higher the better (values 0-30)

disable3rdPerson=0;         // Toggles the 3rd person view for players (value 0-1)
disableCrosshair=0;         // Toggles the cross-hair (value 0-1)

serverTime="SystemTime";    // Initial in-game time of the server. "SystemTime" means the local time of the machine. Another possibility is to set the time to some value in "YYYY/MM/DD/HH/MM" format, f.e. "2015/4/8/17/23" .
serverTimeAcceleration=12;  // Accelerated Time (value 0-24)// This is a time multiplier for in-game time. In this case, the time would move 24 times faster than normal, so an entire day would pass in one hour.
serverTimePersistent=0;     // Persistent Time (value 0-1)// The actual server time is saved to storage, so when active, the next server start will use the saved time value.

guaranteedUpdates=1;        // Communication protocol used with game server (use only number 1)

loginQueueConcurrentPlayers=5;  // The number of players concurrently processed during the login process. Should prevent massive performance drop during connection when a lot of people are connecting at the same time.
loginQueueMaxPlayers=500;       // The maximum number of players that can wait in login queue

instanceId = 1;             // DayZ server instance id, to identify the number of instances per box and their storage folders with persistence files
lootHistory = 1;            // How many persistence history files should be kept by instance, number is looped over during save
storeHouseStateDisabled = false;// Disable houses/doors persistence (value true/false), usable in case of problems with persistence
storageAutoFix = 1;         // Checks if the persistence files are corrupted and replaces corrupted ones with empty ones (value 0-1)

respawnTime = 5;            // Sets the respawn delay (in seconds) before the player is able to get a new character on the server, when the previous one is dead

maxPing= 200;               // Max ping value until server kick the user (value in milliseconds)

steamQueryPort = 2305;      // defines Steam query port, should fix the issue with server not being visible in client server browser

class Missions
{
    class DayZ
    {
        template="dayzOffline.chernarusplus"; // Mission to load on server startup. <MissionName>.<TerrainName>
    };
};
`;

test("updateDayZConfig patches hostname/password/passwordAdmin/maxPlayers with distinctive values", () => {
  const next = updateDayZConfig(REFERENCE, {
    hostname: "NXEON-TEST-7f3a",
    password: "nx-join-9d2c",
    passwordAdmin: "nx-admin-4b1e",
    maxPlayers: "37",
  });

  assert.match(next, /^hostname = "NXEON-TEST-7f3a";/m);
  assert.match(next, /^password = "nx-join-9d2c";/m);
  assert.match(next, /^passwordAdmin = "nx-admin-4b1e";/m);
  // The distinctive value, and NOT quoted (maxPlayers is numeric).
  assert.match(next, /^maxPlayers = 37;/m);
  assert.doesNotMatch(next, /^maxPlayers = "37"/m);
});

test("updateDayZConfig does not corrupt loginQueueMaxPlayers when patching maxPlayers", () => {
  // The real trap this file contains: a naive substring/no-boundary match on
  // "maxPlayers" would also rewrite (or double-rewrite) loginQueueMaxPlayers,
  // which happens to end in the exact same text.
  const next = updateDayZConfig(REFERENCE, { maxPlayers: "12" });
  assert.match(next, /^maxPlayers = 12;/m);
  assert.match(next, /^loginQueueMaxPlayers=500;/m, "loginQueueMaxPlayers must survive untouched");
});

test("updateDayZConfig preserves every untouched line byte-for-byte (comments, spacing, key order)", () => {
  const next = updateDayZConfig(REFERENCE, { hostname: "Nxeon Server" });
  const untouchedKeys = [
    "verifySignatures = 2;",
    "forceSameBuild = 1;",
    "disableVoN = 0;",
    "vonCodecQuality = 20;",
    "instanceId = 1;",
    "steamQueryPort = 2305;",
  ];
  for (const line of untouchedKeys) {
    assert.ok(next.includes(line), `expected untouched line to survive: ${line}`);
  }
  // Comment text on an untouched line survives too.
  assert.ok(next.includes("// Verifies .pbos against .bisign files. (only 2 is supported)"));
});

test("updateDayZConfig escapes an embedded double quote in a string field rather than breaking the file", () => {
  const next = updateDayZConfig(REFERENCE, { hostname: 'Nxeon "Elite" Server' });
  assert.match(next, /^hostname = "Nxeon \\"Elite\\" Server";/m);
});

test("updateDayZConfig appends a missing key rather than silently dropping it", () => {
  const withoutHostname = REFERENCE.split("\n").filter((l) => !l.startsWith("hostname")).join("\n");
  const next = updateDayZConfig(withoutHostname, { hostname: "Nxeon Appended" });
  assert.match(next, /^hostname = "Nxeon Appended";/m);
});

test("updateDayZConfig patches the nested class Missions -> class DayZ -> template (mission/map)", () => {
  const next = updateDayZConfig(REFERENCE, {}, "dayzOffline.enoch");
  assert.match(next, /template="dayzOffline\.enoch";/);
  assert.doesNotMatch(next, /template="dayzOffline\.chernarusplus";/);
  // The surrounding class structure survives — this is a real Bohemia nested
  // config block, not a flat key, and the patch must not flatten it.
  assert.match(next, /class Missions\s*\{\s*class DayZ\s*\{/);
});

test("updateDayZConfig appends a fresh Missions block when one is entirely missing, instead of dropping the map choice", () => {
  const withoutMissions = REFERENCE.replace(/class Missions[\s\S]*$/, "").trimEnd();
  assert.doesNotMatch(withoutMissions, /class Missions/);
  const next = updateDayZConfig(withoutMissions, {}, "dayzOffline.sakhal");
  assert.match(next, /class Missions/);
  assert.match(next, /template="dayzOffline\.sakhal";/);
});

test("updateDayZConfig combines flat updates and the mission template in one pass, leaving everything else untouched", () => {
  const next = updateDayZConfig(
    REFERENCE,
    { hostname: "Nxeon Combined", password: "", passwordAdmin: "combined-admin-pw", maxPlayers: "50" },
    "dayzOffline.enoch"
  );
  assert.match(next, /^hostname = "Nxeon Combined";/m);
  assert.match(next, /^password = "";/m);
  assert.match(next, /^passwordAdmin = "combined-admin-pw";/m);
  assert.match(next, /^maxPlayers = 50;/m);
  assert.match(next, /template="dayzOffline\.enoch";/);
  assert.match(next, /^loginQueueMaxPlayers=500;/m);
  assert.match(next, /^verifySignatures = 2;/m);
});

