// dayz (Wave 11, 2026-09-24): NOT a freshly-generated per-server secret
// like the three above — DayZ's dedicated-server depot (SteamCMD app
// 223350) rejects anonymous login, so every DayZ server needs the SAME
// shared, Nxeon-owned Steam credential just to download the game at all.
// See lib/dayz-steam.ts for the full mechanism (why a dedicated
// download-only account with Steam Guard off, not a customer's own
// login) and the one manual step left (that account doesn't exist yet in
// this environment). When unconfigured, `dayzSteamCredentials()` returns
// null and `applyGameControlSecrets` is called with an empty object —
// its own "only touches a key already present" discipline means the
// setupScript's `-e USERNAME=''` / `-e PASSWRD=''` placeholders are left
// exactly as the catalog seeded them (blank), so SteamCMD attempts, and
// honestly fails, an anonymous login rather than the worker silently
// proceeding as if this were configured. lib/game-order.ts additionally
// refuses new DayZ orders outright while this is unconfigured, so in
// practice this branch with an empty object should never actually run in
// production — kept as defense in depth, not the only gate.
const scriptWithSecrets =
  server.osTemplate.family === "palworld"
    ? applyGameControlSecrets(scriptWithJavaImage, { ADMIN_PASSWORD: generatePassword() })
    : server.osTemplate.family === "rust"
      ? applyGameControlSecrets(scriptWithJavaImage, { RUST_RCON_PASSWORD: generatePassword() })
      : server.osTemplate.family === "cs2"
        ? applyGameControlSecrets(scriptWithJavaImage, { CS2_RCONPW: generatePassword() })
        : server.osTemplate.family === "dayz"
          ? applyGameControlSecrets(
              scriptWithJavaImage,
              (() => {
                const creds = dayzSteamCredentials();
                return creds ? { USERNAME: creds.username, PASSWRD: creds.password } : {};
              })()
            )
          : scriptWithJavaImage;

