import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 10 (2026-09-24).
 *
 * PREVIEW_GAMES.cs16 was authored directly from the real seeded GamePlan
 * rows (prisma/seed-wave10-games.ts — 1GB/16-player $3.99, 2GB/24-player
 * $5.99 popular, 3GB/32-player $7.99), so no price override is needed here.
 */

export const metadata: Metadata = {
  title: "CS 1.6 Server Hosting — Instant Setup",
  description:
    "Managed Counter-Strike 1.6 server hosting from $3.99/mo. AMX Mod X preinstalled, fast-download map hosting, and instant setup on a low-latency Singapore network.",
  alternates: { canonical: "/cs-16-server-hosting" },
  openGraph: {
    type: "article",
    title: "CS 1.6 Server Hosting — Instant Setup",
    description:
      "Managed CS 1.6 hosting: AMX Mod X preinstalled, fast-download map hosting, and instant setup on a low-latency Singapore network. From $3.99/mo.",
    url: `${APP_URL}/cs-16-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.cs16;

const FAQ = [
  {
    q: "What is CS 1.6 server hosting?",
    a: "A dedicated Counter-Strike 1.6 (GoldSrc) server — the classic 2003-era shooter, running on Valve's original free dedicated-server tool with Metamod and AMX Mod X preinstalled for admin commands and plugins.",
  },
  {
    q: "Which plan do I need?",
    a: "The 1 GB / 16-player Casual plan at $3.99 suits pub matches. The 2 GB / 24-player Community plan at $5.99 is our popular pick for a regular community server. Choose the 3 GB / 32-player Tournament plan at $7.99 for scrims and tournament nights.",
  },
  {
    q: "Can I run custom maps?",
    a: "Yes — upload your own map rotation and the built-in fast-download server serves it straight to joining players, no separate download host needed.",
  },
  {
    q: "Does it come with admin plugins?",
    a: "Yes — Metamod and AMX Mod X are preinstalled and ready to configure, so admin commands work from the moment your server comes online.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your CS 1.6 server is provisioned and online within minutes of ordering.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Counter-Strike 2 hosting", href: "/cs2-server-hosting" },
  { label: "Team Fortress 2 hosting", href: "/tf2-server-hosting" },
  { label: "Pricing", href: "/pricing" },
];

export default function Cs16ServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Counter-Strike 1.6 Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
