const FAQ = [
  {
    q: "What is Nightingale?",
    a: "Nightingale is a survival-crafting game set across procedurally-linked fae realms — you and your group step through portals, build estates, and craft your way deeper into a chain of increasingly dangerous realms.",
  },
  {
    q: "Which plan do I need?",
    a: "The 4 GB / 4-player Waystation plan at $8.99 suits a small group hopping between their first few realms. The 6 GB / 6-player Estate plan at $12.99 is our popular pick for pushing deeper into the realm chain. Choose the 8 GB / 8-player Dominion plan at $16.99 for multiple estates and heavy realm-hopping.",
  },
  {
    q: "Can I install mods?",
    a: "Yes — full world-save access means you can drop in community mods and configs alongside your realm saves.",
  },
  {
    q: "Is this a managed server or a VPS I set up myself?",
    a: "It's a fully managed Nightingale server — no manual server setup required from you. Order a plan and it's provisioned and online in minutes, ready for your first portal.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your Nightingale server is provisioned and online within minutes of ordering, so your group can start realm-hopping the same day.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Enshrouded hosting", href: "/enshrouded-server-hosting" },
  { label: "Valheim hosting", href: "/valheim-server-hosting" },
  { label: "Pricing", href: "/pricing" },
];

export default function NightingaleServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Nightingale Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

