30:test("never overrides a TYPE the setupScript already sets explicitly", () => {

import { test } from "node:test";
import assert from "node:assert/strict";
import { applyGameVariant, applyGameConfigEnv } from "../worker/game-variant.ts";

const MC_SCRIPT =
  "curl -fsSL https://get.docker.com | sh && docker run -d --name mc -e EULA=TRUE -e MEMORY=2G -p 25565:25565 -p 25575:25575 -v /opt/mc:/data --restart unless-stopped itzg/minecraft-server";

test("injects -e TYPE=<VARIANT> right after the docker run -d flag", () => {
  const out = applyGameVariant(MC_SCRIPT, "minecraft", "paper");
  assert.match(out, /docker run -d -e TYPE=PAPER --name mc\b/);
  // Nothing else in the script should change.
  assert.equal(out.replace("-e TYPE=PAPER ", ""), MC_SCRIPT);
});

test("uppercases the variant id to match the itzg image's expected TYPE values", () => {
  const out = applyGameVariant(MC_SCRIPT, "minecraft", "vanilla");
  assert.match(out, /-e TYPE=VANILLA\b/);
});

test("is a no-op for non-minecraft families, regardless of variant", () => {
  assert.equal(applyGameVariant(MC_SCRIPT, "terraria", "paper"), MC_SCRIPT);
  assert.equal(applyGameVariant(MC_SCRIPT, null, "paper"), MC_SCRIPT);
});

test("is a no-op when there is no stored variant (legacy servers predating this fix)", () => {
  assert.equal(applyGameVariant(MC_SCRIPT, "minecraft", null), MC_SCRIPT);
  assert.equal(applyGameVariant(MC_SCRIPT, "minecraft", ""), MC_SCRIPT);
});

test("never overrides a TYPE the setupScript already sets explicitly", () => {
  const alreadyTyped = MC_SCRIPT.replace("-e MEMORY=2G", "-e MEMORY=2G -e TYPE=FORGE");
  const out = applyGameVariant(alreadyTyped, "minecraft", "paper");
  assert.equal(out, alreadyTyped);
});

test("matches --detach as well as -d", () => {
  const detachForm = MC_SCRIPT.replace("docker run -d", "docker run --detach");
  const out = applyGameVariant(detachForm, "minecraft", "purpur");
  assert.match(out, /docker run --detach -e TYPE=PURPUR --name mc\b/);
});

// -----------------------------------------------------------------------
// applyGameConfigEnv — the DST TOKEN fix (2026-08-31): checkout-time
// Server.gameConfig values must reach the docker run command, not just get
// stored and ignored the way gameVariant was before applyGameVariant existed.
// -----------------------------------------------------------------------

const DST_SCRIPT =
  "curl -fsSL https://get.docker.com | sh && mkdir -p /opt/dst && docker run -d --name dst --restart unless-stopped -p 10999:10999/udp -e TOKEN='' -e NAME='Nxeon' -e MAX_PLAYERS='10' -e SERVER_PORT='10999' -e GAME_MODE='survival' -v /opt/dst:/data yeetzone/dontstarvetogether:latest";

test("substitutes a customer's cluster TOKEN into the DST setup script", () => {
  const out = applyGameConfigEnv(DST_SCRIPT, "dst", { TOKEN: "abc123XYZ", NAME: "Nxeon", MAX_PLAYERS: 10, PASSWORD: "" });
  assert.match(out, /-e TOKEN='abc123XYZ'/);
});

test("leaves a field alone when the setup script has no matching -e placeholder for it", () => {
  // DST's PASSWORD field exists in the schema but the yeetzone image never wired
  // it to an env var — must be a no-op, never invent a flag that isn't there.
  const out = applyGameConfigEnv(DST_SCRIPT, "dst", { PASSWORD: "hunter2" });
  assert.equal(out, DST_SCRIPT);

