import { test } from "node:test";
import assert from "node:assert/strict";
import { applyGameConfigEnv, applyGameControlSecrets } from "../worker/game-variant.ts";

/**
 * Verifies the DayZ OsTemplate's setupScript (prisma/seed-wave11-dayz.ts) the
 * same way the Arma Reforger/CS 1.6 wave verified theirs: run the REAL script
 * string through the real provisioning-time substitution functions with
 * distinctive test values, and check the resulting docker command directly —
 * deterministic, no VM, no SSH, no Steam account needed.
 *
 * SCRIPT below is copied verbatim from prisma/seed-wave11-dayz.ts — same
 * convention as test/game-variant.test.ts's MC_SCRIPT/DST_SCRIPT constants.
 * Keep it in sync if that file's setupScript ever changes.
 */
const SCRIPT =
  `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/dayz/steamcmd /opt/dayz/serverfiles && docker run -d --name dayz --restart unless-stopped -p 2302-2306:2302-2306/udp -e GAME_ID='223350' -e GAME_PORT='2302' -e UID='99' -e GID='100' -e VALIDATE='true' -e USERNAME='' -e PASSWRD='' -v /opt/dayz/steamcmd:/serverdata/steamcmd -v /opt/dayz/serverfiles:/serverdata/serverfiles ich777/steamcmd:dayz`;

test("the DayZ setupScript really does override GAME_ID to the stable depot (223350), not the image's own experimental default (1042420)", () => {
  assert.match(SCRIPT, /-e GAME_ID='223350'/);
  assert.doesNotMatch(SCRIPT, /1042420/);
});

test("applyGameConfigEnv is a genuine no-op on the DayZ script — confirms the schema fields are NOT docker-env-driven", () => {
  // hostname/password/passwordAdmin/maxPlayers/missionTemplate are all real
  // DAYZ schema field keys (lib/game-config.ts) — none of them appear as
  // `-e KEY=` placeholders in the script (serverDZ.cfg is file-based, applied
  // instead through worker/game-config.ts's applyDayZ). Distinctive test
  // values prove nothing gets silently substituted where nothing should.
  const out = applyGameConfigEnv(SCRIPT, "dayz", {
    hostname: "NXEON-TEST-HOSTNAME-9f2c",
    password: "nx-join-test-pw",
    passwordAdmin: "nx-admin-test-pw",
    maxPlayers: 41,
    missionTemplate: "dayzOffline.enoch",
  });
  assert.equal(out, SCRIPT, "applyGameConfigEnv must not alter the DayZ script at all — none of these fields are env-var-driven");
});

test("applyGameControlSecrets substitutes the platform Steam credential into USERNAME/PASSWRD with distinctive test values", () => {
  const out = applyGameControlSecrets(SCRIPT, {
    USERNAME: "nxeon-dayz-test-account",
    PASSWRD: "correct-horse-battery-staple-9f2c",
  });
  assert.match(out, /-e USERNAME='nxeon-dayz-test-account'/);
  assert.match(out, /-e PASSWRD='correct-horse-battery-staple-9f2c'/);
  // Every other flag survives untouched.
  assert.match(out, /-e GAME_ID='223350'/);
  assert.match(out, /-p 2302-2306:2302-2306\/udp/);
});

test("applyGameControlSecrets called with no credentials (unconfigured — the real state in this environment) leaves the blank placeholders exactly as seeded", () => {
  // Mirrors worker/index.ts:buildCloudInit's actual behavior when
  // lib/dayz-steam.ts's dayzSteamCredentials() returns null: an empty object
  // is passed through, and applyGameControlSecrets's own "only touches a key
  // already present" discipline means the blank placeholders survive
  // untouched — SteamCMD then attempts, and honestly fails, an anonymous
  // login rather than the worker fabricating a value.
  const out = applyGameControlSecrets(SCRIPT, {});
  assert.equal(out, SCRIPT);
  assert.match(out, /-e USERNAME=''/);
  assert.match(out, /-e PASSWRD=''/);
});

test("a value containing a single quote cannot break out of the shell quoting", () => {
  const out = applyGameControlSecrets(SCRIPT, { USERNAME: "nx' ; rm -rf / #", PASSWRD: "pw" });
  assert.match(out, /-e USERNAME='nx'\\''\s*; rm -rf \/ #'/);
});

